fn authorize_body(
    principal: &Principal,
    aliases: &dyn AliasResolver,
    shape: BodyShape,
    body: &[u8],
    default_index: Option<&str>,
) -> Result<(), Response> {
    for (expr, privilege) in body_targets(principal, shape, body, default_index)? {
        authorize_expression(principal, aliases, &expr, privilege, expansion_for(shape))?;
